// Domain: The Work — image assets stored beside task.md in each task folder.
// Images live in `<projectRoot>/docs/tasks/<taskId>/assets/` and are referenced
// from task markdown with relative paths (`![alt](assets/foo.png)`), never
// base64-embedded.
import path from "node:path";
import fs from "node:fs";
import { resolveTasksDir } from "../docsPath.js";

/** Allowed image file extensions (lowercase, without the dot). */
export const IMAGE_EXTENSIONS = ["png", "jpg", "jpeg", "gif", "webp"];

/** Content-Type served for each allowed image extension. */
const IMAGE_MEDIA_TYPES = {
	png: "image/png",
	jpg: "image/jpeg",
	jpeg: "image/jpeg",
	gif: "image/gif",
	webp: "image/webp",
};

/** Maximum sanitized filename length (including extension). */
const MAX_IMAGE_NAME_LENGTH = 120;

/***
 * MARK: isAllowedImageExt
 * @description Whether a filename carries an allowed image extension (png/jpg/jpeg/gif/webp), case-insensitive.
 * @example isAllowedImageExt('photo.PNG') => true
 * @example isAllowedImageExt('payload.svg') => false
 * @param {string} filename
 * @returns {boolean}
 ***/
export function isAllowedImageExt(filename) {
	const ext = path.extname(String(filename || "")).replace(/^\./, "").toLowerCase();
	return IMAGE_EXTENSIONS.includes(ext);
}

/***
 * MARK: imageMediaType
 * @description The Content-Type for an allowed image filename, or null when the extension is not an allowed image type.
 * @example imageMediaType('photo.jpeg') => 'image/jpeg'
 * @param {string} filename
 * @returns {string|null}
 ***/
export function imageMediaType(filename) {
	const ext = path.extname(String(filename || "")).replace(/^\./, "").toLowerCase();
	return IMAGE_MEDIA_TYPES[ext] || null;
}

/***
 * MARK: sanitizeImageName
 * @description Reduces an uploaded filename to a safe, flat asset name: directory
 *   components (and any traversal payloads like `../../etc/passwd`) are stripped to
 *   the final segment, unsafe characters collapse to `-`, leading dots/separators are
 *   trimmed, and the result is lowercased and length-capped. Returns "" when nothing
 *   safe remains. Callers combine this with `isAllowedImageExt` before writing.
 * @example sanitizeImageName('../../etc/passwd.png') => 'passwd.png'
 * @example sanitizeImageName('My Screenshot (1).PNG') => 'my-screenshot-1-.png'
 * @example sanitizeImageName('..') => ''
 * @param {string} rawName
 * @returns {string}
 ***/
export function sanitizeImageName(rawName) {
	if (!rawName || typeof rawName !== "string") return "";
	// Normalize separators and keep only the final path segment: any traversal
	// payload (`../`, `..\`, absolute paths) collapses to the bare filename.
	const base = String(rawName).replace(/\\/g, "/").split("/").pop() || "";
	let name = base
		.normalize("NFKD")
		.replace(/[^A-Za-z0-9._-]+/g, "-")
		.toLowerCase();
	// Split stem/extension so trimming and the length cap never eat the extension.
	// A degenerate trailing dot ("trailing..") is not an extension: it must trim.
	const rawExt = path.extname(name);
	const ext = /^\.[A-Za-z0-9]+$/.test(rawExt) ? rawExt.toLowerCase() : "";
	let stem = ext ? name.slice(0, name.length - rawExt.length) : name;
	stem = stem
		.replace(/-{2,}/g, "-")
		.replace(/^[.-]+/, "")
		.replace(/[.-]+$/g, "");
	name = `${stem}${ext.toLowerCase()}`;
	if (name.length > MAX_IMAGE_NAME_LENGTH) {
		name = `${stem.slice(0, MAX_IMAGE_NAME_LENGTH - ext.length)}${ext.toLowerCase()}`;
	}
	return name;
}

/***
 * MARK: dedupeImageName
 * @description Returns a name that does not collide with the taken names: `foo.png`
 *   becomes `foo-2.png`, `foo-3.png`, … so an upload never overwrites an existing asset.
 * @example dedupeImageName(['a.png'], 'a.png') => 'a-2.png'
 * @param {string[]} existingNames
 * @param {string} name
 * @returns {string}
 ***/
export function dedupeImageName(existingNames, name) {
	const taken = new Set((existingNames || []).map((n) => String(n).toLowerCase()));
	if (!taken.has(name.toLowerCase())) return name;
	const ext = path.extname(name);
	const stem = name.slice(0, name.length - ext.length) || "image";
	for (let n = 2; ; n += 1) {
		const candidate = `${stem}-${n}${ext}`;
		if (!taken.has(candidate.toLowerCase())) return candidate;
	}
}

/***
 * MARK: taskAssetDir
 * @description The absolute assets directory for one task: `<projectCwd>/<docsDirName>/tasks/<taskId>/assets`.
 *   The taskId is verified against traversal: the resolved folder must keep the
 *   requested taskId as its final segment. `docsDirName` is the project's
 *   custom link-folder name (or project record); absent means the `docs` default.
 * @example taskAssetDir('/repo', 'task-1') => '/repo/docs/tasks/task-1/assets'
 * @param {string} projectCwd
 * @param {string} taskId
 * @param {Object|string} [docsProject] - Project record (or bare folder name) carrying `docsDirName`.
 * @returns {string|null} Absolute path, or null when the taskId escapes the tasks root.
 ***/
export function taskAssetDir(projectCwd, taskId, docsProject) {
	if (!projectCwd || !taskId || typeof taskId !== "string") return null;
	const project =
		typeof docsProject === "string" ? { docsDirName: docsProject } : docsProject;
	const tasksRoot = resolveTasksDir(projectCwd, project) || path.resolve(projectCwd, "docs", "tasks");
	const taskFolder = path.resolve(tasksRoot, taskId);
	if (path.basename(taskFolder) !== taskId) return null;
	if (path.relative(tasksRoot, taskFolder).startsWith("..")) return null;
	return path.join(taskFolder, "assets");
}

/***
 * MARK: resolveTaskAssetFile
 * @description The absolute file path for one sanitized asset name inside a task's
 *   assets directory, or null when the name is unsafe. The name MUST already be
 *   sanitized (flat, no directories) — traversal is impossible by construction.
 * @example resolveTaskAssetFile('/repo', 'task-1', 'a.png') => '/repo/docs/tasks/task-1/assets/a.png'
 * @param {string} projectCwd
 * @param {string} taskId
 * @param {string} name
 * @returns {string|null}
 ***/
export function resolveTaskAssetFile(projectCwd, taskId, name, docsProject) {
	const assetsDir = taskAssetDir(projectCwd, taskId, docsProject);
	if (!assetsDir || !name) return null;
	const safeName = sanitizeImageName(name);
	if (!safeName || safeName !== name) return null;
	return path.join(assetsDir, safeName);
}

/***
 * MARK: taskAssetRelPath
 * @description The markdown-reference form for an asset name (what `![alt](…)` carries).
 * @example taskAssetRelPath('a.png') => 'assets/a.png'
 * @param {string} name
 * @returns {string}
 ***/
export function taskAssetRelPath(name) {
	return `assets/${name}`;
}

/***
 * MARK: listTaskImages
 * @description Lists the image assets stored in a task's assets directory, sorted by
 *   name. Missing directories yield an empty list (a task without images is normal).
 * @example listTaskImages('/repo', 'task-1') => [{ name: 'a.png', path: 'assets/a.png', size: 512, mtime: '...', mediaType: 'image/png' }]
 * @param {string} projectCwd
 * @param {string} taskId
 * @returns {Array<{name: string, path: string, size: number, mtime: string, mediaType: string|null}>}
 ***/
export function listTaskImages(projectCwd, taskId, docsProject) {
	const assetsDir = taskAssetDir(projectCwd, taskId, docsProject);
	if (!assetsDir) return [];
	/* eslint-disable security/detect-non-literal-fs-filename */
	try {
		if (!fs.existsSync(assetsDir)) return [];
		return fs
			.readdirSync(assetsDir, { withFileTypes: true })
			.filter((entry) => entry.isFile() && isAllowedImageExt(entry.name))
			.map((entry) => {
				let size = 0;
				let mtime = "";
				try {
					const stat = fs.statSync(path.join(assetsDir, entry.name));
					size = stat.size;
					mtime = stat.mtime.toISOString();
				} catch {
					// Unreadable entry: keep it listed with empty stats.
				}
				return {
					name: entry.name,
					path: taskAssetRelPath(entry.name),
					size,
					mtime,
					mediaType: imageMediaType(entry.name),
				};
			})
			.sort((a, b) => a.name.localeCompare(b.name));
	} catch {
		return [];
	}
	/* eslint-enable security/detect-non-literal-fs-filename */
}

/***
 * MARK: collectTaskImageRefs
 * @description The capped list of relative image references for prompt injection:
 *   `assets/<name>` strings, at most `maxRefs` of them (overflow is the caller's concern).
 * @example collectTaskImageRefs('/repo', 'task-1', 10) => ['assets/a.png', 'assets/b.png']
 * @param {string} projectCwd
 * @param {string} taskId
 * @param {number} [maxRefs=10]
 * @returns {string[]}
 ***/
export function collectTaskImageRefs(projectCwd, taskId, maxRefs = 10, docsProject) {
	const cap = Number.isFinite(maxRefs) && maxRefs > 0 ? Math.floor(maxRefs) : 10;
	return listTaskImages(projectCwd, taskId, docsProject)
		.slice(0, cap)
		.map((image) => image.path);
}

/***
 * MARK: writeTaskImage
 * @description Writes an image buffer into a task's assets directory (creating it when
 *   needed). The name must already be sanitized and extension-allowed — callers own that
 *   check. Returns the relative markdown-reference path.
 * @example writeTaskImage('/repo', 'task-1', 'a.png', buffer) => 'assets/a.png'
 * @param {string} projectCwd
 * @param {string} taskId
 * @param {string} name
 * @param {Buffer} buffer
 * @returns {string} Relative asset path (`assets/<name>`).
 ***/
export function writeTaskImage(projectCwd, taskId, name, buffer, docsProject) {
	const assetsDir = taskAssetDir(projectCwd, taskId, docsProject);
	if (!assetsDir || !name || !Buffer.isBuffer(buffer)) {
		throw new Error("Invalid task image write");
	}
	/* eslint-disable security/detect-non-literal-fs-filename */
	fs.mkdirSync(assetsDir, { recursive: true });
	fs.writeFileSync(path.join(assetsDir, name), buffer);
	/* eslint-enable security/detect-non-literal-fs-filename */
	return taskAssetRelPath(name);
}

/***
 * MARK: deleteTaskImage
 * @description Removes one image asset from a task's assets directory. Returns whether a file was actually removed.
 * @example deleteTaskImage('/repo', 'task-1', 'a.png') => true
 * @param {string} projectCwd
 * @param {string} taskId
 * @param {string} name
 * @returns {boolean}
 ***/
export function deleteTaskImage(projectCwd, taskId, name, docsProject) {
	const assetsDir = taskAssetDir(projectCwd, taskId, docsProject);
	if (!assetsDir || !name) return false;
	const safeName = sanitizeImageName(name);
	if (!safeName) return false;
	/* eslint-disable security/detect-non-literal-fs-filename */
	try {
		const target = path.join(assetsDir, safeName);
		if (!fs.existsSync(target)) return false;
		fs.rmSync(target, { force: true });
		return true;
	} catch {
		return false;
	}
	/* eslint-enable security/detect-non-literal-fs-filename */
}

/***
 * MARK: taskImagesRoutes
 * @description Task image asset endpoints: multipart upload into the task folder's
 *   `assets/` directory, listing, binary-safe serving, and per-image removal.
 *   Images are stored at `<projectCwd>/docs/tasks/<taskId>/assets/<name>` and
 *   referenced from task markdown with relative paths (`![alt](assets/<name>)`).
 *   Guards: extension allowlist, per-file size cap, per-task count cap, sanitized
 *   filenames (traversal payloads collapse to the bare name), and a taskId check
 *   that keeps the resolved folder inside `docs/tasks/`.
 * @example app.register(taskImagesRoutes, { deps })
 ***/

import fs from "node:fs";
import path from "node:path";
import {
	isAllowedImageExt,
	imageMediaType,
	sanitizeImageName,
	dedupeImageName,
	taskAssetDir,
	resolveTaskAssetFile,
	listTaskImages,
	writeTaskImage,
	deleteTaskImage,
} from "../work/taskAssets.js";
import { config as appConfig } from "../config.js";

/***
 * MARK: resolveTaskContext
 * @description Guards + resolves the on-disk task folder for a task-scoped image
 *   request: the project must exist, the taskId must resolve inside `docs/tasks/`,
 *   and the task must exist (in the store, or as task.md on disk for tasks the
 *   store has not hydrated yet). Sends the error response and returns null when
 *   any guard fails.
 * @example const ctx = resolveTaskContext(deps, request, reply); if (!ctx) return;
 * @param {Object} deps - Injected route dependencies (projectStore, taskStore).
 * @param {Object} request - Fastify request (params.id, params.taskId).
 * @param {Object} reply - Fastify reply.
 * @returns {{project: Object, taskId: string, projectCwd: string}|null}
 ***/
function resolveTaskContext(deps, request, reply) {
	const { resolveAndGuardProject, projectStore, taskStore } = deps;
	const projectId = resolveAndGuardProject(
		request.params?.id || request.query?.projectId,
		reply,
	);
	if (!projectId) return null;
	const project = projectStore.getProject(projectId);
	if (!project) {
		request.log?.warn?.(
			{ projectId, reason: "unknown-project" },
			"task image request for an unknown project",
		);
		reply.status(404).send({ error: "Project not found", reason: "unknown-project" });
		return null;
	}
	// Repair-after-switch BEFORE the existence check: a branch checkout may
	// have dropped the `<cwd>/docs` symlink, and without the repair the
	// task folder below resolves into a shadow directory — task.md (and the
	// assets beside it) looks missing and every image 404s until some later
	// save happens to repair the link. Never throws: link verification must
	// not fail an image read.
	try {
		taskStore?._repairDocsLinkAfterSwitch?.(projectId, project.cwd);
	} catch {
		// Ignore: serving falls back to whatever is on disk.
	}
	const taskId = String(request.params?.taskId || "").trim();
	const assetsDir = taskAssetDir(project.cwd, taskId, project);
	if (!assetsDir) {
		request.log?.warn?.(
			{ projectId, taskId, reason: "invalid-task-id" },
			"task image request with an invalid task id",
		);
		reply.status(400).send({ error: "Invalid task id", reason: "invalid-task-id" });
		return null;
	}
	// Server-authoritative task existence: the store is primary; task.md on
	// disk is the fallback (covers tasks not yet rehydrated into the cache).
	const taskFolder = path.dirname(assetsDir);
	const taskExists =
		Boolean(taskStore?.getTask?.(projectId, taskId)) ||
		fs.existsSync(path.join(taskFolder, "task.md"));
	if (!taskExists) {
		request.log?.warn?.(
			{ projectId, taskId, reason: "task-not-found" },
			"task image request for a task with no task.md",
		);
		reply.status(404).send({ error: "Task not found", reason: "task-not-found" });
		return null;
	}
	return { project, taskId, projectCwd: project.cwd };
}

/***
 * MARK: taskImagesRoutes
 * @description Registers the task image endpoints on the Fastify app.
 * @param {Object} app - Fastify application instance.
 * @param {Object} opts - Options including injected deps.
 ***/
export default async function taskImagesRoutes(app, { deps }) {
	const { projectStore, taskStore } = deps;

	/***
	 * MARK: Upload Task Image
	 * @description Stores one multipart `image` file in the task's assets folder.
	 *   Rejects non-multipart requests (400), disallowed extensions / non-image
	 *   declared MIME (400), files over the size cap (413) and uploads past the
	 *   per-task count cap (413). The stored name is sanitized + deduped, so a
	 *   second `foo.png` upload becomes `foo-2.png` instead of overwriting.
	 ***/
	app.post(
		"/projects/:id/tasks/:taskId/images",
		{
			schema: {
				params: {
					type: "object",
					properties: { id: { type: "string" }, taskId: { type: "string" } },
				},
				response: {
					201: {
						type: "object",
						properties: {
							name: { type: "string" },
							path: { type: "string" },
							url: { type: "string" },
							size: { type: "number" },
						},
					},
					400: {
						type: "object",
						properties: { error: { type: "string" }, reason: { type: "string" } },
					},
					404: {
						type: "object",
						properties: { error: { type: "string" }, reason: { type: "string" } },
					},
					413: {
						type: "object",
						properties: { error: { type: "string" }, reason: { type: "string" } },
					},
				},
			},
		},
		async (request, reply) => {
			const ctx = resolveTaskContext(
				{ resolveAndGuardProject: deps.resolveAndGuardProject, projectStore, taskStore },
				request,
				reply,
			);
			if (!ctx) return;

			if (!request.isMultipart()) {
				return reply.status(400).send({
					error: "multipart/form-data request with an 'image' file is required",
				});
			}

			let file;
			try {
				file = await request.file();
			} catch (err) {
				const tooLarge = err?.statusCode === 413 || err?.code === "FST_REQ_FILE_TOO_LARGE";
				return reply.status(tooLarge ? 413 : 400).send({
					error: tooLarge
						? `Image exceeds the ${appConfig.taskImageMaxBytes} byte limit`
						: `Invalid multipart payload: ${err?.message || "unknown error"}`,
				});
			}
			if (!file || file.type !== "file") {
				return reply
					.status(400)
					.send({ error: "An 'image' file field is required" });
			}

			const declaredType = String(file.mimetype || "").toLowerCase();
			if (declaredType && !declaredType.startsWith("image/")) {
				return reply
					.status(400)
					.send({ error: `Unsupported upload type: ${declaredType}` });
			}

			const safeName = sanitizeImageName(file.filename);
			if (!safeName || !isAllowedImageExt(safeName)) {
				return reply.status(400).send({
					error:
						"Only png, jpg, jpeg, gif and webp images are supported (filename was sanitized to nothing usable)",
				});
			}

			let buffer;
			try {
				buffer = await file.toBuffer();
			} catch (err) {
				const tooLarge =
					err?.code === "FST_REQ_FILE_TOO_LARGE" || err?.statusCode === 413;
				return reply.status(tooLarge ? 413 : 400).send({
					error: tooLarge
						? `Image exceeds the ${appConfig.taskImageMaxBytes} byte limit`
						: `Upload could not be read: ${err?.message || "unknown error"}`,
				});
			}

			// Repair-after-switch (see TaskStore._saveTaskMarkdown): asset
			// writes mkdir the task dir directly and would cement a shadow
			// directory when the docs link is missing.
			taskStore._repairDocsLinkAfterSwitch?.(
				request.params.id,
				ctx.projectCwd,
			);
			const existing = listTaskImages(ctx.projectCwd, ctx.taskId, ctx.project);
			if (existing.length >= appConfig.taskImageMaxPerTask) {
				return reply.status(413).send({
					error: `Task image limit reached (${appConfig.taskImageMaxPerTask} per task)`,
				});
			}

			const finalName = dedupeImageName(
				existing.map((image) => image.name),
				safeName,
			);
			const relPath = writeTaskImage(ctx.projectCwd, ctx.taskId, finalName, buffer, ctx.project);
			return reply.status(201).send({
				name: finalName,
				path: relPath,
				url: taskImageUrl(request.params.id, ctx.taskId, finalName),
				size: buffer.length,
			});
		},
	);

	/***
	 * MARK: List Task Images
	 * @description Lists the image assets stored for one task.
	 ***/
	app.get(
		"/projects/:id/tasks/:taskId/images",
		{
			schema: {
				params: {
					type: "object",
					properties: { id: { type: "string" }, taskId: { type: "string" } },
				},
				response: {
					200: {
						type: "object",
						properties: {
							taskId: { type: "string" },
							images: {
								type: "array",
								items: {
									type: "object",
									properties: {
										name: { type: "string" },
										path: { type: "string" },
										size: { type: "number" },
										mtime: { type: "string" },
										mediaType: { type: ["string", "null"] },
									},
								},
							},
						},
					},
					404: {
						type: "object",
						properties: { error: { type: "string" }, reason: { type: "string" } },
					},
				},
			},
		},
		async (request, reply) => {
			const ctx = resolveTaskContext(
				{ resolveAndGuardProject: deps.resolveAndGuardProject, projectStore, taskStore },
				request,
				reply,
			);
			if (!ctx) return;
			return {
				taskId: ctx.taskId,
				images: listTaskImages(ctx.projectCwd, ctx.taskId, ctx.project),
			};
		},
	);

	/***
	 * MARK: Serve Task Image
	 * @description Binary-safe image serving: exact stored bytes with the correct
	 *   Content-Type, inline disposition and nosniff — never the UTF-8 text
	 *   endpoint (`/files/content`), which corrupts binaries.
	 ***/
	app.get(
		"/projects/:id/tasks/:taskId/images/:name",
		{
			schema: {
				params: {
					type: "object",
					properties: {
						id: { type: "string" },
						taskId: { type: "string" },
						name: { type: "string" },
					},
				},
				response: {
					400: {
						type: "object",
						properties: { error: { type: "string" }, reason: { type: "string" } },
					},
					403: {
						type: "object",
						properties: { error: { type: "string" }, reason: { type: "string" } },
					},
					404: {
						type: "object",
						properties: { error: { type: "string" }, reason: { type: "string" } },
					},
				},
			},
		},
		async (request, reply) => {
			const ctx = resolveTaskContext(
				{ resolveAndGuardProject: deps.resolveAndGuardProject, projectStore, taskStore },
				request,
				reply,
			);
			if (!ctx) return;

			const requestedName = String(request.params?.name || "");
			if (requestedName.includes("/") || requestedName.includes("\\")) {
				request.log?.warn?.(
					{ projectId: ctx.project?.id, taskId: ctx.taskId, reason: "path-traversal" },
					"task image request with a path separator in the name",
				);
				return reply
					.status(403)
					.send({ error: "Forbidden: Path traversal detected", reason: "path-traversal" });
			}
			const safeName = sanitizeImageName(requestedName);
			if (!safeName || !isAllowedImageExt(safeName)) {
				request.log?.warn?.(
					{ taskId: ctx.taskId, name: requestedName, reason: "invalid-image-name" },
					"task image request with an invalid image name",
				);
				return reply
					.status(400)
					.send({ error: "Invalid image name", reason: "invalid-image-name" });
			}
			let targetFile = resolveTaskAssetFile(ctx.projectCwd, ctx.taskId, safeName, ctx.project);
			// Serve-side canonicalization for stale/unsanitized refs: a stored
			// ref may carry a non-canonical name (wrong case, spaces, trailing
			// title residue) that the backend flattened on upload. Resolve to
			// an existing asset whose sanitized name matches instead of 404ing
			// a file that is actually present under a nearby canonical name.
			if (!targetFile || !fs.existsSync(targetFile)) {
				const assetsDir = taskAssetDir(ctx.projectCwd, ctx.taskId, ctx.project);
				if (assetsDir) {
					try {
						const match = fs
							.readdirSync(assetsDir, { withFileTypes: true })
							.find(
								(entry) =>
									entry.isFile() &&
									isAllowedImageExt(entry.name) &&
									sanitizeImageName(entry.name) === safeName,
							);
						if (match) {
							targetFile = path.join(assetsDir, match.name);
						}
					} catch {
						// Missing/unreadable directory: fall through to 404 below.
					}
				}
			}
			/* eslint-disable security/detect-non-literal-fs-filename */
			if (!targetFile || !fs.existsSync(targetFile)) {
				request.log?.warn?.(
					{ taskId: ctx.taskId, name: safeName, reason: "image-not-found" },
					"task image request for a missing asset file",
				);
				return reply.status(404).send({ error: "Image not found", reason: "image-not-found" });
			}
			const servedName = path.basename(targetFile);
			try {
				const buffer = fs.readFileSync(targetFile);
				const mediaType = imageMediaType(servedName) || "application/octet-stream";
				reply
					.header("content-type", mediaType)
					.header("content-length", buffer.length)
					.header("content-disposition", `inline; filename="${servedName}"`)
					.header("x-content-type-options", "nosniff")
					// Stored names are write-once (uploads dedupe instead of
					// overwriting, deletes are explicit), so bytes are
					// immutable: refreshes must not revalidate into a
					// transient miss the way `max-age=60` did.
					.header("cache-control", "private, max-age=31536000, immutable");
				return reply.send(buffer);
			} catch (err) {
				return reply
					.status(500)
					.send({ error: `Failed to read image: ${err.message}` });
			}
			/* eslint-enable security/detect-non-literal-fs-filename */
		},
	);

	/***
	 * MARK: Delete Task Image
	 * @description Removes one image asset from the task's assets folder.
	 ***/
	app.delete(
		"/projects/:id/tasks/:taskId/images/:name",
		{
			schema: {
				params: {
					type: "object",
					properties: {
						id: { type: "string" },
						taskId: { type: "string" },
						name: { type: "string" },
					},
				},
				response: {
					200: {
						type: "object",
						properties: { status: { type: "string" }, name: { type: "string" } },
					},
					400: {
						type: "object",
						properties: { error: { type: "string" }, reason: { type: "string" } },
					},
					404: {
						type: "object",
						properties: { error: { type: "string" }, reason: { type: "string" } },
					},
				},
			},
		},
		async (request, reply) => {
			const ctx = resolveTaskContext(
				{ resolveAndGuardProject: deps.resolveAndGuardProject, projectStore, taskStore },
				request,
				reply,
			);
			if (!ctx) return;
			const safeName = sanitizeImageName(String(request.params?.name || ""));
			if (!safeName) {
				return reply
					.status(400)
					.send({ error: "Invalid image name", reason: "invalid-image-name" });
			}
			const removed = deleteTaskImage(ctx.projectCwd, ctx.taskId, safeName, ctx.project);
			if (!removed) {
				return reply.status(404).send({ error: "Image not found", reason: "image-not-found" });
			}
			return { status: "deleted", name: safeName };
		},
	);
}

/***
 * MARK: taskImageUrl
 * @description The API-relative URL for one stored task image (what the frontend embeds in `src`).
 * @example taskImageUrl('p1', 't1', 'a.png') => '/projects/p1/tasks/t1/images/a.png'
 * @param {string} projectId
 * @param {string} taskId
 * @param {string} name
 * @returns {string}
 ***/
export function taskImageUrl(projectId, taskId, name) {
	return `/projects/${encodeURIComponent(projectId)}/tasks/${encodeURIComponent(taskId)}/images/${encodeURIComponent(name)}`;
}

