import React, { useState, useMemo, useCallback, useEffect, useRef } from 'react';
import { API_BASE } from '../../services/apiBase';
import { resolveTaskImageUrl } from '../../services/taskImages';

/***
 * MARK: sanitizeUrl
 * @description Validates and sanitizes link URLs to prevent XSS (blocks javascript:, data:, vbscript:).
 * @param {string} url - The URL to sanitize.
 * @returns {string} Safe URL or '#' fallback.
 * @example sanitizeUrl('https://example.com') => 'https://example.com'
 ***/
export function sanitizeUrl(url) {
  if (!url || typeof url !== 'string') return '#';
  const trimmed = url.trim();
  // Disallow javascript:, data:, vbscript: protocols
  if (/^(javascript|data|vbscript):/i.test(trimmed)) {
    return '#';
  }
  return trimmed;
}

/***
 * MARK: highlightCode
 * @description Lightweight tokenizer that syntax-highlights code lines with JetBrains Mono role chromatics.
 * @param {string} code - The code block content.
 * @param {string} language - The programming language identifier.
 * @returns {React.ReactNode[]} Array of formatted lines / tokens.
 * @example highlightCode('const x = 42;', 'js') => [<span ...>...</span>]
 ***/
export function highlightCode(code, _language = '') {
  if (!code) return null;
  const lines = code.split('\n');

  return lines.map((line, lineIdx) => {
    // If comment line
    if (/^\s*(\/\/|#|\/\*|\*)/.test(line)) {
      return (
        <div key={lineIdx} className="text-text-muted italic">
          {line || '\u00A0'}
        </div>
      );
    }

    // Tokenize line by strings, keywords, numbers
    const parts = [];
    let lastIndex = 0;
    const tokenRegex =
      /("([^"\\]|\\.)*"|'([^'\\]|\\.)*'|`([^`\\]|\\.)*`|\/\/.*$|#.*$|\b(?:const|let|var|function|return|if|else|import|export|from|class|def|async|await|for|while|try|catch|throw|switch|case|break|continue|default|new|typeof|instanceof|in|of|yield|type|interface|extends|implements|public|private|protected|readonly|static|void|null|undefined|true|false|None|True|False)\b|\b\d+(\.\d+)?\b)/g;

    let match;
    while ((match = tokenRegex.exec(line)) !== null) {
      if (match.index > lastIndex) {
        parts.push(line.slice(lastIndex, match.index));
      }
      const token = match[0];
      if (token.startsWith('"') || token.startsWith("'") || token.startsWith('`')) {
        parts.push(
          <span key={`${lineIdx}-${match.index}`} className="text-ochre">
            {token}
          </span>,
        );
      } else if (token.startsWith('//') || token.startsWith('#')) {
        parts.push(
          <span key={`${lineIdx}-${match.index}`} className="text-text-muted italic">
            {token}
          </span>,
        );
      } else if (/^\d+(\.\d+)?$/.test(token)) {
        parts.push(
          <span key={`${lineIdx}-${match.index}`} className="text-[#ffb0b0]">
            {token}
          </span>,
        );
      } else {
        parts.push(
          <span key={`${lineIdx}-${match.index}`} className="text-primary font-semibold">
            {token}
          </span>,
        );
      }
      lastIndex = tokenRegex.lastIndex;
    }

    if (lastIndex < line.length) {
      parts.push(line.slice(lastIndex));
    }

    return (
      <div key={lineIdx} className="leading-5">
        {parts.length > 0 ? parts : '\u00A0'}
      </div>
    );
  });
}

/***
 * MARK: CodeBlock
 * @description Syntax-highlighted code container with header bar, language badge, and copy button.
 * @param {Object} props
 * @param {string} props.code - The raw code string.
 * @param {string} [props.language] - The detected language.
 * @param {boolean} [props.enableCopy=true] - Whether to show the copy button.
 * @example <CodeBlock code="console.log('hi')" language="js" />
 ***/
export function CodeBlock({ code, language = '', enableCopy = true }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = useCallback(() => {
    if (typeof navigator !== 'undefined' && navigator.clipboard) {
      navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  }, [code]);

  return (
    <div className="my-3 rounded-sm border border-border-standard bg-surface-deep overflow-hidden font-mono text-xs">
      {/* Code Header */}
      <div className="flex items-center justify-between px-3 py-1.5 bg-surface-container border-b border-border-standard">
        <span className="font-label-caps text-[10px] uppercase font-bold text-text-muted tracking-wider">
          {(language || 'CODE').toUpperCase()}
        </span>
        {enableCopy && (
          <button
            type="button"
            onClick={handleCopy}
            aria-label="Copy code block to clipboard"
            className="px-2 py-0.5 rounded text-[10px] font-mono font-bold uppercase tracking-wider text-text-muted hover:text-on-surface hover:bg-surface-container-high border border-border-standard transition-all cursor-pointer"
          >
            {copied ? 'Copied ✓' : 'Copy'}
          </button>
        )}
      </div>
      {/* Code Content */}
      <pre className="p-3 overflow-x-auto text-on-surface custom-scrollbar leading-relaxed">
        <code>{highlightCode(code, language)}</code>
      </pre>
    </div>
  );
}

/***
 * MARK: MdImage
 * @description An inline markdown image with graceful degradation: task-asset and
 *   http(s) sources render as lazy-loaded images; a broken/unavailable image falls
 *   back to an inert filename chip instead of a broken-image icon; URLs the
 *   sanitizer neutralized (javascript:/data:/vbscript: → '#') render as inert text.
 * @example <MdImage src="/projects/p/tasks/t/images/a.png" alt="screenshot" />
 * @param {Object} props
 * @param {string} props.src - The resolved, sanitized image URL.
 * @param {string} [props.alt] - The markdown alt text.
 ***/
export function MdImage({ src, alt = '' }) {
  const [failed, setFailed] = useState(false);
  // Bumped to force a fresh load attempt for the same URL (manual or
  // automatic retry); without a key change the <img> would never refetch.
  const [retryKey, setRetryKey] = useState(0);
  // A transient failure (slow/flaky load, cold cache) gets exactly one
  // automatic re-attempt; anything beyond that is a real miss and latches.
  const autoRetriedRef = useRef(false);
  const prevSrcRef = useRef(src);

  // Reset latched failure state whenever the source changes, including
  // direct prop updates that do not remount the component. A fresh source
  // must always start with a clean load attempt.
  useEffect(() => {
    if (prevSrcRef.current === src) return;
    prevSrcRef.current = src;
    setFailed(false);
    setRetryKey(0);
    autoRetriedRef.current = false;
  }, [src]);

  useEffect(() => {
    if (!failed || autoRetriedRef.current) return undefined;
    autoRetriedRef.current = true;
    const timer = setTimeout(() => {
      setFailed(false);
      setRetryKey((key) => key + 1);
    }, 1500);
    return () => clearTimeout(timer);
  }, [failed]);

  const retry = useCallback(() => {
    autoRetriedRef.current = true;
    setFailed(false);
    setRetryKey((key) => key + 1);
  }, []);

  if (!src || src === '#') {
    return (
      <span
        className="inline-flex items-center gap-1 font-mono text-[10px] text-text-muted bg-surface-container border border-border-standard rounded px-1.5 py-0.5 align-middle"
        role="img"
        aria-label={alt || 'blocked image'}
      >
        ⛔ {alt || 'image'} (blocked URL)
      </span>
    );
  }

  if (failed) {
    const name = (() => {
      try {
        return decodeURIComponent(src.split('/').pop() || '') || alt || 'image';
      } catch {
        return alt || 'image';
      }
    })();
    return (
      <span className="inline-flex items-center gap-1 font-mono text-[10px] text-text-muted bg-surface-container border border-border-standard rounded px-1.5 py-0.5 align-middle">
        <span role="img" aria-label={alt || name}>
          🖼️ {name} (image unavailable)
        </span>
        <button
          type="button"
          onClick={retry}
          aria-label={`Retry loading ${name}`}
          className="underline underline-offset-2 hover:text-on-surface transition-colors cursor-pointer"
        >
          Retry
        </button>
      </span>
    );
  }

  return (
    <img
      key={retryKey}
      src={src}
      alt={alt}
      loading="lazy"
      onError={() => setFailed(true)}
      className="max-w-full h-auto rounded border border-border-standard my-2 inline-block"
    />
  );
}

/***
 * MARK: parseInlineMarkdown
 * @description Recursively parses inline markdown syntax (bold, italic, strike, code, links, images).
 * @param {string} text - Raw inline text.
 * @param {Object} [imageContext] - Task context for relative image resolution ({ apiBase, projectId, taskId }).
 * @returns {React.ReactNode[]} Array of React nodes.
 * @example parseInlineMarkdown('Hello **world** and `code`') => ['Hello ', <strong>world</strong>, ' and ', <code>code</code>]
 ***/
export function parseInlineMarkdown(text, imageContext = {}) {
  if (!text || typeof text !== 'string') return [];

  // Match bold-italic, bold, italic, strikethrough, inline-code, links, images
  const inlineRegex =
    /(!?\[([^\]]*)\]\(([^)]+)\)|`([^`]+)`|\*\*\*([^*]+)\*\*\*|___([^_]+)___|\*\*([^*]+)\*\*|__([^_]+)__|~~([^~]+)~~|\*([^*]+)\*|_([^_]+)_)/g;

  const nodes = [];
  let lastIdx = 0;
  let match;

  while ((match = inlineRegex.exec(text)) !== null) {
    if (match.index > lastIdx) {
      nodes.push(text.slice(lastIdx, match.index));
    }

    const fullMatch = match[0];
    const key = `inline-${match.index}`;

    if (fullMatch.startsWith('!') && match[2] !== undefined && match[3] !== undefined) {
      // Image: ![alt](url) — relative task-asset paths resolve to the raw
      // image endpoint; the sanitizer still blocks javascript:/data:/vbscript:.
      // The src joins the key so a new source remounts with fresh load
      // state instead of inheriting a latched failure from the old URL.
      const alt = match[2];
      const src = sanitizeUrl(resolveTaskImageUrl({ ...imageContext, src: match[3] }));
      nodes.push(<MdImage key={`${key}:${src}`} src={src} alt={alt} />);
    } else if (match[2] !== undefined && match[3] !== undefined) {
      // Link: [label](url)
      const label = match[2];
      const href = sanitizeUrl(match[3]);
      nodes.push(
        <a
          key={key}
          href={href}
          target="_blank"
          rel="noopener noreferrer"
          className="text-secondary hover:text-secondary/80 underline underline-offset-2 transition-colors cursor-pointer font-medium"
        >
          {parseInlineMarkdown(label, imageContext)}
        </a>,
      );
    } else if (match[4] !== undefined) {
      // Inline code: `code`
      nodes.push(
        <code
          key={key}
          className="font-mono bg-surface-container px-1.5 py-0.5 rounded text-primary text-xs border border-border-standard/40"
        >
          {match[4]}
        </code>,
      );
    } else if (match[5] !== undefined || match[6] !== undefined) {
      // Bold Italic: ***text*** or ___text___
      const inner = match[5] || match[6];
      nodes.push(
        <strong key={key} className="font-bold text-on-surface">
          <em className="italic">{parseInlineMarkdown(inner, imageContext)}</em>
        </strong>,
      );
    } else if (match[7] !== undefined || match[8] !== undefined) {
      // Bold: **text** or __text__
      const inner = match[7] || match[8];
      nodes.push(
        <strong key={key} className="font-bold text-on-surface">
          {parseInlineMarkdown(inner, imageContext)}
        </strong>,
      );
    } else if (match[9] !== undefined) {
      // Strikethrough: ~~text~~
      nodes.push(
        <del key={key} className="line-through text-text-muted">
          {parseInlineMarkdown(match[9], imageContext)}
        </del>,
      );
    } else if (match[10] !== undefined || match[11] !== undefined) {
      // Italic: *text* or _text_
      const inner = match[10] || match[11];
      nodes.push(
        <em key={key} className="italic text-on-surface">
          {parseInlineMarkdown(inner, imageContext)}
        </em>,
      );
    }

    lastIdx = inlineRegex.lastIndex;
  }

  if (lastIdx < text.length) {
    nodes.push(text.slice(lastIdx));
  }

  return nodes.length > 0 ? nodes : [text];
}

/***
 * MARK: parseMarkdownBlocks
 * @description Parses multiline markdown content into structured AST blocks (headings, code blocks, lists, tables, quotes, hr, paragraphs).
 * @param {string} markdown - The markdown raw string.
 * @returns {Array<Object>} List of parsed block objects.
 * @example parseMarkdownBlocks('# Title\n\nContent') => [{ type: 'h1', text: 'Title' }, { type: 'p', text: 'Content' }]
 ***/
export function parseMarkdownBlocks(markdown) {
  if (!markdown || typeof markdown !== 'string') return [];

  const lines = markdown.replace(/\r\n/g, '\n').split('\n');
  const blocks = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    // 1. Fenced Code Block: ```lang
    if (line.trim().startsWith('```')) {
      const language = line.trim().replace(/^```/, '').trim();
      const codeLines = [];
      i += 1;
      while (i < lines.length && !lines[i].trim().startsWith('```')) {
        codeLines.push(lines[i]);
        i += 1;
      }
      blocks.push({
        type: 'code',
        language,
        code: codeLines.join('\n'),
      });
      i += 1;
      continue;
    }

    // 2. Horizontal Rule: --- or *** or ___
    if (/^(\s*[-*_]\s*){3,}$/.test(line)) {
      blocks.push({ type: 'hr' });
      i += 1;
      continue;
    }

    // 3. Headings: # H1 through ###### H6
    const headingMatch = line.match(/^(#{1,6})\s+(.*)$/);
    if (headingMatch) {
      const level = headingMatch[1].length;
      blocks.push({
        type: `h${level}`,
        text: headingMatch[2].trim(),
      });
      i += 1;
      continue;
    }

    // 4. Blockquotes: > quote
    if (line.trim().startsWith('>')) {
      const quoteLines = [];
      while (i < lines.length && lines[i].trim().startsWith('>')) {
        quoteLines.push(lines[i].replace(/^>\s?/, ''));
        i += 1;
      }
      blocks.push({
        type: 'blockquote',
        text: quoteLines.join('\n'),
      });
      continue;
    }

    // 5. Table: lines starting and ending with |
    if (line.trim().startsWith('|') && line.trim().endsWith('|')) {
      const tableLines = [];
      while (i < lines.length && lines[i].trim().startsWith('|') && lines[i].trim().endsWith('|')) {
        tableLines.push(lines[i].trim());
        i += 1;
      }
      if (tableLines.length >= 2) {
        const headerRow = tableLines[0]
          .split('|')
          .slice(1, -1)
          .map((c) => c.trim());
        // line 1 is often separator |---|---|
        const dataRows = tableLines
          .slice(1)
          .filter((l) => !/^\|(\s*[-:]+\s*\|)+$/.test(l))
          .map((row) =>
            row
              .split('|')
              .slice(1, -1)
              .map((c) => c.trim()),
          );
        blocks.push({
          type: 'table',
          headers: headerRow,
          rows: dataRows,
        });
        continue;
      }
    }

    // 6. Unordered List: - item, * item, + item
    if (/^\s*[-*+]\s+/.test(line)) {
      const items = [];
      while (i < lines.length && /^\s*[-*+]\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*[-*+]\s+/, ''));
        i += 1;
      }
      blocks.push({
        type: 'ul',
        items,
      });
      continue;
    }

    // 7. Ordered List: 1. item
    if (/^\s*\d+\.\s+/.test(line)) {
      const items = [];
      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*\d+\.\s+/, ''));
        i += 1;
      }
      blocks.push({
        type: 'ol',
        items,
      });
      continue;
    }

    // 8. Empty line -> skip
    if (!line.trim()) {
      i += 1;
      continue;
    }

    // 9. Paragraph
    const paragraphLines = [];
    while (
      i < lines.length &&
      lines[i].trim() &&
      !lines[i].trim().startsWith('```') &&
      !lines[i].match(/^(#{1,6})\s+/) &&
      !lines[i].trim().startsWith('>') &&
      !/^\s*[-*+]\s+/.test(lines[i]) &&
      !/^\s*\d+\.\s+/.test(lines[i]) &&
      !(lines[i].trim().startsWith('|') && lines[i].trim().endsWith('|')) &&
      !/^(\s*[-*_]\s*){3,}$/.test(lines[i])
    ) {
      paragraphLines.push(lines[i]);
      i += 1;
    }

    if (paragraphLines.length > 0) {
      blocks.push({
        type: 'p',
        text: paragraphLines.join(' '),
      });
    }
  }

  return blocks;
}

/***
 * MARK: MarkdownViewer
 * @description Lightweight, secure Markdown renderer supporting headings (h1-h6),
 * bullet/numbered lists, bold/italic, inline code, syntax-highlighted code blocks,
 * markdown links, blockquotes, and tables without dangerous HTML injection.
 * @param {Object} props
 * @param {string} [props.content=''] - The markdown content to render.
 * @param {string} [props.className=''] - Optional outer container CSS classes.
 * @param {boolean} [props.enableCopy=true] - Whether code blocks have copy buttons.
 * @param {string} [props.projectId] - Task context so relative `assets/...` image references resolve to the raw image endpoint.
 * @param {string} [props.taskId] - Task context for image resolution (see resolveTaskImageUrl).
 * @example <MarkdownViewer content="# Overview\n\nTask details here." />
 ***/
export function MarkdownViewer({
  content = '',
  className = '',
  enableCopy = true,
  projectId = null,
  taskId = null,
}) {
  // Relative task-asset images resolve against the task's image endpoint;
  // without task context, sources render as-is (legacy behavior).
  const imageContext = useMemo(
    () => ({ apiBase: API_BASE, projectId, taskId }),
    [projectId, taskId],
  );
  const blocks = useMemo(() => parseMarkdownBlocks(content), [content]);

  if (!content || blocks.length === 0) {
    return (
      <div className={`text-text-muted text-xs italic ${className}`}>No content provided.</div>
    );
  }

  return (
    <div
      data-testid="markdown-viewer"
      className={`markdown-viewer space-y-2.5 text-xs text-on-surface leading-relaxed min-w-0 max-w-full break-words overflow-x-clip ${className}`}
    >
      {blocks.map((block, idx) => {
        switch (block.type) {
          case 'h1':
            return (
              <h1
                key={idx}
                className="font-display-lg text-xl font-bold text-on-surface mt-4 mb-2 tracking-tight break-words min-w-0 max-w-full"
              >
                {parseInlineMarkdown(block.text, imageContext)}
              </h1>
            );
          case 'h2':
            return (
              <h2
                key={idx}
                className="font-headline-md text-base font-bold text-on-surface mt-3.5 mb-1.5 border-b border-border-standard/60 pb-1 break-words min-w-0 max-w-full"
              >
                {parseInlineMarkdown(block.text, imageContext)}
              </h2>
            );
          case 'h3':
            return (
              <h3
                key={idx}
                className="font-headline-sm text-sm font-semibold text-primary mt-3 mb-1 break-words min-w-0 max-w-full"
              >
                {parseInlineMarkdown(block.text, imageContext)}
              </h3>
            );
          case 'h4':
            return (
              <h4
                key={idx}
                className="text-xs font-semibold text-secondary mt-2 mb-0.5 uppercase tracking-wide font-mono"
              >
                {parseInlineMarkdown(block.text, imageContext)}
              </h4>
            );
          case 'h5':
            return (
              <h5
                key={idx}
                className="text-[11px] font-semibold text-ochre mt-1.5 mb-0.5 uppercase tracking-wider font-mono"
              >
                {parseInlineMarkdown(block.text, imageContext)}
              </h5>
            );
          case 'h6':
            return (
              <h6
                key={idx}
                className="text-[10px] font-bold text-text-muted mt-1 mb-0.5 uppercase tracking-widest font-mono"
              >
                {parseInlineMarkdown(block.text, imageContext)}
              </h6>
            );
          case 'p':
            return (
              <p
                key={idx}
                className="text-xs font-body-md text-on-surface leading-relaxed break-words min-w-0 max-w-full"
              >
                {parseInlineMarkdown(block.text, imageContext)}
              </p>
            );
          case 'code':
            return (
              <CodeBlock
                key={idx}
                code={block.code}
                language={block.language}
                enableCopy={enableCopy}
              />
            );
          case 'ul':
            return (
              <ul key={idx} className="space-y-1 my-2 pl-2">
                {block.items.map((item, itemIdx) => (
                  <li key={itemIdx} className="flex items-start gap-2 text-xs">
                    <span className="text-primary select-none mt-0.5">•</span>
                    <span className="flex-1">{parseInlineMarkdown(item, imageContext)}</span>
                  </li>
                ))}
              </ul>
            );
          case 'ol':
            return (
              <ol key={idx} className="space-y-1 my-2 pl-2">
                {block.items.map((item, itemIdx) => (
                  <li key={itemIdx} className="flex items-start gap-2 text-xs">
                    <span className="font-mono text-[10px] font-bold text-secondary select-none mt-0.5">
                      {itemIdx + 1}.
                    </span>
                    <span className="flex-1">{parseInlineMarkdown(item, imageContext)}</span>
                  </li>
                ))}
              </ol>
            );
          case 'blockquote':
            return (
              <blockquote
                key={idx}
                className="border-l-2 border-primary/70 pl-3 py-1.5 my-2 italic text-text-muted bg-surface-container/30 rounded-r text-xs leading-relaxed"
              >
                {parseInlineMarkdown(block.text, imageContext)}
              </blockquote>
            );
          case 'hr':
            return <hr key={idx} className="border-border-standard my-3" />;
          case 'table':
            return (
              <div
                key={idx}
                className="overflow-x-auto my-3 border border-border-standard rounded-sm"
              >
                <table className="zebra-table w-full border-collapse text-xs font-mono text-left">
                  {block.headers && block.headers.length > 0 && (
                    <thead className="bg-surface-container border-b border-border-standard">
                      <tr>
                        {block.headers.map((h, hIdx) => (
                          <th
                            key={hIdx}
                            className="p-2 font-bold uppercase text-[10px] tracking-wider text-text-muted border-r border-border-standard last:border-r-0"
                          >
                            {parseInlineMarkdown(h, imageContext)}
                          </th>
                        ))}
                      </tr>
                    </thead>
                  )}
                  <tbody>
                    {block.rows.map((row, rIdx) => (
                      <tr
                        key={rIdx}
                        className="zebra-row border-b border-border-standard/50 last:border-b-0 hover:bg-surface-container-high/30 transition-colors"
                      >
                        {row.map((cell, cIdx) => (
                          <td
                            key={cIdx}
                            className="p-2 border-r border-border-standard/50 last:border-r-0 text-on-surface"
                          >
                            {parseInlineMarkdown(cell, imageContext)}
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            );
          default:
            return null;
        }
      })}
    </div>
  );
}

export default MarkdownViewer;

// Domain: The Work — task image assets (upload, list, delete) and the
// markdown image-URL resolution the inline renderer relies on.

/***
 * MARK: resolveTaskImageUrl
 * @description Turns a markdown image src into a fetchable URL. Relative task
 *   asset paths (`assets/<name>`, with optional leading `./` or `/` or a fuller
 *   task-folder prefix) are rewritten to the binary-safe task image endpoint;
 *   absolute http(s) URLs pass through untouched; protocol-blocked values
 *   (javascript:, data:, vbscript:) also pass through UNCHANGED so the
 *   viewer's sanitizeUrl stays the single place that neutralizes them.
 *   Without task context the src is returned as-is (legacy behavior).
 * @example resolveTaskImageUrl({ apiBase: 'http://localhost:3100', projectId: 'p1', taskId: 't1', src: 'assets/shot.png' })
 *   => 'http://localhost:3100/projects/p1/tasks/t1/images/shot.png'
 * @example resolveTaskImageUrl({ projectId: 'p1', taskId: 't1', src: 'https://x/y.png' }) => 'https://x/y.png'
 * @param {Object} opts
 * @param {string} [opts.apiBase] - The API origin ('' = same origin).
 * @param {string} [opts.projectId]
 * @param {string} [opts.taskId]
 * @param {string} [opts.src] - The markdown image src.
 * @returns {string}
 ***/
export function resolveTaskImageUrl({ apiBase = '', projectId, taskId, src }) {
  if (!src || typeof src !== 'string') return '';
  const trimmed = src.trim();
  if (!trimmed) return '';
  // Absolute and protocol URLs are not task assets — leave them for the sanitizer.
  if (/^(https?:)?\/\//i.test(trimmed) || /^[a-z][a-z0-9+.-]*:/i.test(trimmed)) {
    return trimmed;
  }
  if (!projectId || !taskId) return trimmed;
  // CommonMark image destinations may carry a trailing quoted title
  // (`![a](assets/a.png "shot")`); resolve on the bare destination so the
  // title never becomes part of the requested asset name.
  const resolvedSrc = firstSrcToken(trimmed);
  const assetMatch = resolvedSrc.match(/(?:^|\/)(assets\/[^/?#]+)$/);
  if (!assetMatch) return trimmed;
  const base = String(apiBase || '').replace(/\/+$/, '');
  return `${base}/projects/${encodeURIComponent(projectId)}/tasks/${encodeURIComponent(taskId)}/images/${encodeURIComponent(assetMatch[1].slice('assets/'.length))}`;
}

/***
 * MARK: taskImageRequests
 * @description Task image asset requests (upload/list/delete) using the app's
 *   existing connection and request helper.
 * @example const requests = taskImageRequests(request); await requests.upload(projectId, taskId, file)
 * @param {Function} request - The shared JSON request helper (FormData-aware).
 ***/
export function taskImageRequests(request) {
  return {
    uploadTaskImage: (projectId, taskId, file) => {
      const formData = new FormData();
      formData.append('image', file, file?.name || 'image');
      return request(`/projects/${projectId}/tasks/${taskId}/images`, {
        method: 'POST',
        body: formData,
      });
    },
    listTaskImages: (projectId, taskId) => request(`/projects/${projectId}/tasks/${taskId}/images`),
    deleteTaskImage: (projectId, taskId, name) =>
      request(`/projects/${projectId}/tasks/${taskId}/images/${encodeURIComponent(name)}`, {
        method: 'DELETE',
      }),
  };
}

/***
 * MARK: isImageFile
 * @description Whether a File looks like an uploadable task image (png/jpg/jpeg/gif/webp) by extension.
 * @example isImageFile(new File([], 'a.png')) => true
 * @param {File} file
 * @returns {boolean}
 ***/
export function isImageFile(file) {
  if (!file || typeof file.name !== 'string') return false;
  return /\.(png|jpe?g|gif|webp)$/i.test(file.name);
}

/***
 * MARK: appendImageMarkdown
 * @description Appends an uploaded image's markdown reference (`![name](path)`)
 *   at the end of a feedback/goal draft on its own new line, regardless of
 *   caret position. Same end-append contract the goal editor uses, shared so
 *   the reject dialogs compose identically. The path is sanitized so a
 *   hostile stored name cannot break out of the `(...)` destination (parens,
 *   quotes, and newlines are stripped) — defense in depth on top of the
 *   backend's `sanitizeImageName`.
 * @example appendImageMarkdown('Fix it', { name: 'a.png', path: 'assets/a.png' }) => 'Fix it\n\n![a.png](assets/a.png)\n'
 * @param {string} text - Current draft text.
 * @param {Object} image - Stored asset `{ name, path }`.
 * @returns {string} Draft with the reference appended.
 ***/
export function appendImageMarkdown(text, image) {
  const base = typeof text === 'string' ? text : '';
  const rawPath = typeof image?.path === 'string' ? image.path.trim() : '';
  if (!rawPath) return base;
  // Alt text must stay on one line inside brackets: strip brackets/newlines
  // so a hostile or pasted filename cannot break out of the image syntax.
  const alt = String(image?.name || 'image')
    .replace(/[\[\]\r\n]+/g, ' ')
    .trim()
    .slice(0, 120);
  // The destination must stay on one line and cannot contain parens or
  // quotes — otherwise a crafted path could close the `(...)` early and
  // inject arbitrary markdown. Stripping is lossless for real asset paths
  // (backend `sanitizeImageName` already produces flat, safe names).
  const dest = rawPath.replace(/[()"'\r\n]+/g, ' ').trim();
  if (!dest) return base;
  const snippet = `![${alt || 'image'}](${dest})`;
  if (!base) return `${snippet}\n`;
  const prefix = base.endsWith('\n\n') ? '' : base.endsWith('\n') ? '\n' : '\n\n';
  return `${base}${prefix}${snippet}\n`;
}

/***
 * MARK: appendImagesMarkdown
 * @description Folds `appendImageMarkdown` over a batch of stored assets so one
 *   multi-select/paste gesture lands as sequential `![name](path)` lines, in
 *   order, via a single text update (no stale-closure accumulation loss).
 *   Entries without a usable path are skipped.
 * @example appendImagesMarkdown('Fix it', [{ name: 'a.png', path: 'assets/a.png' }, { name: 'b.png', path: 'assets/b.png' }]) => 'Fix it\n\n![a.png](assets/a.png)\n\n![b.png](assets/b.png)\n'
 * @param {string} text - Current draft text.
 * @param {Array<Object>} images - Stored assets (`{ name, path }`), in link order.
 * @returns {string} Draft with every reference appended.
 ***/
export function appendImagesMarkdown(text, images) {
  if (!Array.isArray(images) || images.length === 0) {
    return typeof text === 'string' ? text : '';
  }
  return images.reduce((draft, image) => appendImageMarkdown(draft, image), text);
}

/***
 * MARK: firstSrcToken
 * @description Normalizes a markdown image destination to its comparable src:
 *   unwraps the `<...>` form CommonMark allows for spaced destinations, then
 *   strips a trailing quoted title (`![a](x "t")`). An unquoted remainder is
 *   kept whole so stored paths containing spaces still resolve (the image
 *   endpoint percent-encodes them downstream).
 * @example firstSrcToken('assets/a.png "shot"') => 'assets/a.png'
 * @param {string} dest - Raw destination inside the parens.
 * @returns {string} Normalized src ('' when empty).
 ***/
function firstSrcToken(dest) {
  const unwrapped = String(dest || '')
    .trim()
    .replace(/^<|>$/g, '');
  const titled = unwrapped.match(/^(.*?)\s+["'][^"']*["']\s*$/);
  return (titled ? titled[1] : unwrapped).trim();
}

/***
 * MARK: removeImageMarkdown
 * @description Strips the markdown reference line(s) for a removed image asset
 *   from a feedback draft. Matches by exact stored path first, falling back to
 *   the asset basename so hand-edited alt text still strips.
 * @example removeImageMarkdown('Fix it\n\n![a.png](assets/a.png)\n', 'a.png') => 'Fix it'
 * @param {string} text - Current draft text.
 * @param {string} name - Removed asset name (`a.png`).
 * @param {string} [path] - Removed asset path (`assets/a.png`).
 * @returns {string} Draft without that image's reference lines.
 ***/
export function removeImageMarkdown(text, name, path) {
  if (!text || typeof text !== 'string' || !name) return text || '';
  const source = text;
  const lines = source.split('\n');
  let removed = false;
  const kept = lines.filter((line) => {
    const trimmed = line.trim();
    // Tolerate an optional trailing title (`![a](x "t")`): compare on the
    // first whitespace-separated token inside the parens.
    const match = trimmed.match(/^!\[[^\]]*\]\(([^)]+)\)$/);
    if (!match) return true;
    const src = firstSrcToken(match[1]);
    const drop =
      (typeof path === 'string' && path && src === path) || src.split('/').pop() === name;
    if (drop) removed = true;
    return !drop;
  });
  if (!removed) return source;
  // Removing a line can strand double blank lines; collapse runs of three
  // or more newlines and drop trailing whitespace (submit trims anyway).
  return kept
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/\s+$/, '');
}

/***
 * MARK: extractImageRefs
 * @description Collects markdown image references (`![alt](src)`) from a text
 *   draft, in order. Used to render thumbnails for image refs inside
 *   otherwise plain-text rejection reasons.
 * @example extractImageRefs('See ![a](assets/a.png)') => [{ alt: 'a', src: 'assets/a.png' }]
 * @param {string} text - Draft text to scan.
 * @returns {Array<{alt: string, src: string}>} Image references found.
 ***/
export function extractImageRefs(text) {
  if (!text || typeof text !== 'string') return [];
  const refs = [];
  const pattern = /!\[([^\]]*)\]\(([^)]+)\)/g;
  let match;
  while ((match = pattern.exec(text)) !== null) {
    const src = firstSrcToken(match[2]);
    if (!src) continue;
    refs.push({ alt: match[1], src });
  }
  return refs;
}

